tr.g:evaluate:
var id = jelly.jvar_result.sys_id;
var link = jelly.jvar_result.link;
var number = jelly.jvar_result.number;
var commentTruncated = jelly.jvar_result.comments.truncated;
var commentComplete = jelly.jvar_result.comments.complete;
var created = jelly.jvar_result.sys_created_on;
var user = jelly.jvar_result.user;

td.script:
function openSuggestForm${jvar_index}(elem) {
    var suggestionId = elem.readAttribute("data-id");
    var dialogClass = window.GlideModalForm ? GlideModalForm : GlideDialogForm
    var dialog = new dialogClass("${gs.getMessage('Suggested edit')}", "kb_feedback");
    dialog.setPreference("sys_id", suggestionId);
    dialog.addParm("sysparm_view", "suggested_edit");
    dialog.render();
}
